import type { Metadata } from "next";
const product = { name: "Sac de voyage", description: "Sac cabine robuste", slug: "sac-voyage" };
export const metadata: Metadata = {
  title: `${product.name} | L’ecomax`,
  description: product.description,
  alternates: { canonical: `/produit/${product.slug}` },
  openGraph: { title: product.name, description: product.description },
};

exercise.solution:
في SEO التقني والبيانات الوصفية يحافظ الحل على سلطة واحدة ويطبق تحديدًا «توليد البيانات الوصفية من مصدر المنتج المتحقق نفسه المستخدم في العرض مع رابط إنتاج مطلق ثابت». يجعل ترث كل صفحات المنتجات بيانات التخطيط فلا تعود العناكب تميز المنتجات قابلًا للتكرار ثم مضبوطًا ولا يُقبل إلا عندما يحتوي HTML المبني عنوانًا مميزًا ووصفًا مفيدًا والرابط الأساسي المتوقع وبيانات Open Graph مطابقة للمحتوى.
